-- own Russian slug/title/body, internal links inside the body still point
-- at the English URLs (those verticals aren't translated yet).
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ('ab1e2d65-3568-448b-99e6-7947be01903c', 'article', 'ru', 'aeroport-male-velana-international-airport', 'Аэропорт Мале | Velana International Airport', 'Узнайте всё, что нужно знать об аэропорте Мале, также известном как Velana International Airport, главных воздушных воротах Мальдив. Информация о рейсах, инфраструктуре и многом другом.', null, '<h2>Введение</h2><p>Velana International Airport, широко известный как аэропорт <a href="/maldives/islands/male/">Мале</a>, — главные международные воздушные ворота к потрясающим островам Мальдив. Расположенный на острове Хулхуле, недалеко от столицы Мале, этот аэропорт служит важнейшим узлом для путешественников со всего мира. Благодаря современной инфраструктуре, широкой маршрутной сети и первоклассному сервису аэропорт Мале играет жизненно важную роль в мальдивской туристической индустрии, обслуживая миллионы пассажиров ежегодно.</p><p>Мальдивы славятся своими идиллическими пляжами, кристально чистой водой и роскошными курортами. Приезжаете ли вы в семейный отпуск, романтическое путешествие или смелую поездку в одиночку — ваше путешествие начинается в Velana International Airport. Этот гид подробно расскажет обо всём, что нужно знать об аэропорте Мале, включая его историю, инфраструктуру, варианты транспорта и советы по поездке.</p><h4>Быстрая навигация</h4><p>Обзор аэропорта Информация о рейсах Инфраструктура и услуги Транспорт и доступность Советы путешественникам по Velana International Airport Карта аэропорта Мальдив Чем заняться в аэропорту Мальдив Список аэропортов Мальдив Часто задаваемые вопросы</p><h2>Обзор аэропорта</h2><p>Velana International Airport (IATA: MLE, ICAO: VRMM) — самый загруженный и значимый аэропорт Мальдив, служащий главным пунктом въезда как для иностранных туристов, так и для внутренних путешественников. Стратегическое расположение аэропорта на острове Хулхуле, рядом со столицей Мале, делает его важнейшим узлом для авиасообщения в регионе.</p><p>Первоначально известный как Hulhule Airport, он был открыт в 1960 году и с тех пор прошёл через несколько этапов расширения и модернизации, чтобы справляться с растущим числом гостей Мальдив. В 2017 году аэропорт был переименован в Velana International Airport в честь Ибрагима Насира, второго президента Мальдив, сыгравшего значительную роль в развитии страны. Сегодня Velana International Airport оснащён современной инфраструктурой, включая новую взлётно-посадочную полосу, способную принимать крупнейшие самолёты в мире, такие как Airbus A380.</p>', 'Аэропорт Мале | Velana International Airport | Путеводитель по Мальдивам | MTG', 'Узнайте всё, что нужно знать об аэропорте Мале, также известном как Velana International Airport, главных воздушных воротах Мальдив. Информация о рейсах, инфраструктуре и многом другом.', 'published', 'claude'),
  ('5866f31e-2c89-4adb-8cd0-6cc9381a6f98', 'article', 'ru', 'rybalka-atoll-gaafu-guide-lodzh-charter-maamendhoo', 'Рыбалка на атолле Гаафу: гид по нашему лоджу и чартеру на Маамендху', 'Чартерная лодка, цены и многодневные пакеты, которые мы предлагаем из собственного лоджа на острове Маамендху, атолл Гаафу Алифу.', null, '<p>Маамендху, остров на атолле Гаафу Алифу на юге Мальдив, — место, где находится наш собственный лодж и работающий рядом с ним чартерный бизнес. Этот гид рассказывает о лодке, ценах на чартер и многодневных пакетах, построенных вокруг неё.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge.jpeg" alt="Maldives Fishing and Holidays Lodge, Маамендху, атолл Гаафу Алифу" loading="lazy" /></figure><h2>Лодж</h2><p><a href="/maldives/guesthouses/maldives-fishing-and-holidays-lodge/">Наш лодж</a> — это гестхаус на Маамендху с номерами полного пансиона на двух гостей каждый, которым управляет тот же оператор, что и рыболовными чартерами, — поэтому проживание и рыбалку можно забронировать в одном месте, а не организовывать отдельно.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge-hotel.jpeg" alt="Maldives Fishing and Holidays Lodge" loading="lazy" /></figure><h2>Лодка</h2><p>Чартеры проходят на борту «Emperor» — 32-футовой рыболовной лодки с двумя подвесными моторами по 200 л.с. и максимальной вместимостью 5 пассажиров.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-charter-boat.webp" alt="Чартерная лодка для рыбалки на Мальдивах" loading="lazy" /></figure><h2>Цены на частный чартер</h2><p>Два частных чартера можно забронировать напрямую, цена указана за лодку, а не за человека:</p><ul><li><a href="/maldives/fishing/private-full-day-fishing-charter/">Частный чартер на полный день</a> — от 1380 USD за лодку, около 8 часов.</li><li><a href="/maldives/fishing/private-half-day-fishing-charter/">Частный чартер на полдня</a> — от 980 USD за лодку, около 4 часов.</li></ul><h2>Многодневные рыболовные пакеты</h2><p>Помимо двух самостоятельных чартеров, оператор предлагает 14 многодневных пакетов продолжительностью от 2 до 8 ночей, каждый доступен в формате рыбалки на полный день или на полдня, включая проживание в лодже, обратный внутренний перелёт, трансфер на лодке и соответствующее количество дней чартера. Цены зависят от размера группы от 1 до 5 гостей, делящих лодку, при этом 5 гостей получают лучшую цену на человека. <a href="/maldives/packages/2-night-maldives-fishing-package-full-day-fishing/">Пакет на 2 ночи</a> и <a href="/maldives/packages/8-night-maldives-fishing-package-full-day-fishing/">пакет на 8 ночей</a> обозначают два конца этого диапазона — полный <a href="/maldives/packages/fishing/">список рыболовных пакетов</a> показывает все доступные варианты продолжительности.</p><h2>Как добраться</h2><p>Пакеты, построенные вокруг Маамендху, объединяют обратный внутренний перелёт с трансфером на лодке до острова, организованным как часть пакета, а не отдельно.</p><h2>Бронирование</h2><p>Все вышеперечисленные варианты бронируются по запросу — свяжитесь с нами через <a href="/maldives/providers/maldives-fishing-and-holiday/">страницу оператора</a> или начните со страницы чартера или пакета, который подходит для вашей поездки.</p>', 'Рыбалка на атолле Гаафу: гид по нашему лоджу и чартеру на Маамендху | Путеводитель по Мальдивам | MTG', 'Чартерная лодка, цены и многодневные пакеты, которые мы предлагаем из собственного лоджа на острове Маамендху, атолл Гаафу Алифу.', 'published', 'claude'),
  ('01cfff09-ef6a-4503-81a0-77c7e43de561', 'article', 'ru', 'tehniki-rybalki-maldivy-trolling-dzhigging-popping-ruchnaya-leska', 'Техники рыбалки на Мальдивах: троллинг, джиггинг, поппинг и ловля на ручную леску', 'Простое руководство по основным техникам рыбалки, используемым на мальдивских атоллах — троллинг, джиггинг, поппинг и ловля на ручную леску — и какие виды рыб ловят каждой из них.', null, '<p>Большинство рыболовных поездок, которые бронируют на Мальдивах, относятся к одной из нескольких техник, каждая из которых подходит для разных видов рыб и разных участков воды. Этот гид объясняет, в чём заключается каждая техника и что вы, скорее всего, поймаете с её помощью.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/maldives-atoll-aerial-view.webp" alt="Вид на мальдивский атолл с воздуха" loading="lazy" /></figure><h2>Троллинг</h2><p>Троллинг — это проводка лесок с приманками или наживкой за движущейся лодкой, обычно вдоль края атолла или свала рифа, где проходит пелагическая рыба. Это стандартная техника для вахоо — одной из самых быстрых рыб в океане, способной развивать скорость до 80 км/ч, — а также используется для жёлтопёрого тунца и корифены, которых часто находят у плавающего мусора.</p><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Вахоо на Мальдивах" loading="lazy" /></figure><h2>Джиггинг</h2><p>Джиггинг — это вертикальная проводка утяжелённой металлической приманки у дна, над глубокими свалами и склонами рифа, а не на открытой воде, где работает троллинг. Этот метод чаще всего ассоциируется с зубастым тунцом — одиночным, упорным хищником, обитающим именно в таких местах.</p><figure><img src="legacy/fishing/images/dogtooth-tuna-in-maldives.webp" alt="Зубастый тунец на Мальдивах" loading="lazy" /></figure><h2>Поппинг</h2><p>Поппинг — это заброс поверхностной приманки к краю рифа или в каналы и её проводка резкими, брызгающими рывками, чтобы спровоцировать атаку с поверхности, а не из глубины. Это техника теснее всего связана с гигантским каранксом, для ловли которого Мальдивы международно признаны одним из лучших направлений.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/giant-trevally.webp" alt="Гигантский каранкс, пойманный на рыбалке на Мальдивах" loading="lazy" /></figure><h2>Ловля на ручную леску и донная ловля</h2><p>Ловля на ручную леску — катушка, леска, крючок и наживка, управляемые вручную, а не забрасываемые и выматываемые, — традиционная техника с самым низким порогом входа, обычно предлагаемая как вводная поездка на закате и не требующая опыта. Она также лежит в основе исторической мальдивской отрасли ловли полосатого тунца удочкой и леской. Донная ловля, тесно связанная техника, при которой рыбачат на якоре над рифовыми структурами, — обычный способ ловли груперов и люциановых.</p><figure><img src="legacy/images/fishing/tuna-fish-in-maldives.webp" alt="Полосатый тунец на Мальдивах" loading="lazy" /></figure><figure><img src="uploads/assets/uploads/fishing/images/gallery/reef-fishing-grouper.webp" alt="Групер, пойманный на рифе на Мальдивах" loading="lazy" /></figure><h2>Выбор техники</h2><p>Если вы хотите лёгкую, непринуждённую первую поездку, ловля на ручную леску или поездка на закате не требует опыта. Если вы охотитесь за конкретным трофейным видом, техника зависит от рыбы: троллинг для вахоо и тунца, джиггинг для зубастого тунца, поппинг для гигантского каранкса. Наши собственные <a href="/maldives/providers/maldives-fishing-and-holiday/">частные чартеры</a> с Маамендху охватывают троллинг и донную ловлю на борту «Emperor» — смотрите нашу страницу <a href="/maldives/fishing/private-full-day-fishing-charter/">чартера на полный день</a> или изучите полный <a href="/maldives/fishing/#fish-species">гид по видам рыб</a>, чтобы узнать больше о том, что вы можете поймать.</p>', 'Техники рыбалки на Мальдивах: троллинг, джиггинг, поппинг и ловля на ручную леску | Путеводитель по Мальдивам | MTG', 'Простое руководство по основным техникам рыбалки, используемым на мальдивских атоллах — троллинг, джиггинг, поппинг и ловля на ручную леску — и какие виды рыб ловят каждой из них.', 'published', 'claude'),
  ('30c570fb-7ff9-464f-9ed1-1c56807b293f', 'article', 'ru', 'sezony-rybalki-maldivy-guide-po-mesyatsam', 'Сезоны рыбалки на Мальдивах: гид по месяцам', 'Когда лучше ловить каждый вид на мальдивских атоллах — от сезона тунца и вахоо во время северо-восточного муссона до последующего сезона гигантского каранкса.', null, '<p>Условия рыбалки на Мальдивах меняются вместе с двумя муссонными сезонами страны, и у нескольких видов рыб, ради которых сюда приезжают рыболовы, есть собственный сезон в рамках этого цикла. Этот гид показывает, что реально наиболее продуктивно и когда, опираясь на те же данные о видах, которые используются во всём нашем <a href="/maldives/fishing/">гиде по рыбалке на Мальдивах</a>.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-liveaboard-maldives.webp" alt="Лайвабоард для рыбалки на Мальдивах" loading="lazy" /></figure><h2>Два муссона</h2><p>Мальдивы находятся в зоне тропического муссонного климата с двумя основными сезонами. Северо-восточный муссон, местно называемый Ируваи, длится примерно с декабря по апрель и приносит более спокойное море и меньше дождей — самое предсказуемое окно для морских поездок любого типа. Юго-западный муссон, Хулхангу, длится примерно с мая по ноябрь, с большим количеством дождей и более неспокойной водой в отдельные дни, хотя поездки продолжаются на протяжении всего периода, а некоторые из лучших видов для спортивной рыбалки более активны именно в это время.</p><h2>Лучший сезон по видам</h2><p>Вот сезонные закономерности по видам, которые рассматриваются в нашем <a href="/maldives/fishing/#fish-species">гиде по видам рыб</a>:</p><ul><li><strong>Жёлтопёрый тунец</strong> — с декабря по март, во время более спокойного северо-восточного муссона.</li><li><strong>Вахоо</strong> — с декабря по март, в то же окно, обычно ловится троллингом.</li><li><strong>Корифена (махи-махи)</strong> — с декабря по апрель, часто рядом с плавающим мусором и FAD (устройствами для концентрации рыбы).</li><li><strong>Зубастый тунец</strong> — с ноября по апрель, на более глубоких свалах и склонах рифа.</li><li><strong>Гигантский каранкс</strong> — с апреля по октябрь, захватывая переход к юго-западному муссону.</li><li><strong>Полосатый тунец</strong> — круглый год, основа традиционной мальдивской отрасли ловли удочкой и леской.</li></ul><h2>С декабря по апрель: сезон северо-восточного муссона</h2><p>Это окно, когда жёлтопёрый тунец, вахоо и корифена находятся в сезоне одновременно, а более спокойное море делает дни на воде комфортнее, а условия для троллинга вдоль краёв атолла — лучше.</p><figure><img src="legacy/fishing/images/yellowfin-tuna.webp" alt="Жёлтопёрый тунец на Мальдивах" loading="lazy" /></figure><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Вахоо на Мальдивах" loading="lazy" /></figure><h2>С апреля по октябрь: сезон гигантского каранкса</h2><p>По мере того как сезон смещается к юго-западному муссону, наступает сезон гигантского каранкса. GT считается знаковой целью спортивной рыбалки на Мальдивах, патрулирует края рифов и каналы и известен взрывными атаками — страна входит в число лучших направлений в мире для ловли трофейного гигантского каранкса.</p><figure><img src="legacy/images/fishing/giant-trevally-fish.webp" alt="Гигантский каранкс на Мальдивах" loading="lazy" /></figure><h2>Бронирование с учётом сезона</h2><p>Наш собственный <a href="/maldives/providers/maldives-fishing-and-holiday/">чартерный бизнес</a> круглый год предлагает частные чартеры с Маамендху на атолле Гаафу Алифу на борту лодки «Emperor» — смотрите наши страницы чартера на <a href="/maldives/fishing/private-full-day-fishing-charter/">полный день</a> и <a href="/maldives/fishing/private-half-day-fishing-charter/">полдня</a> для актуальных цен, или прочитайте полный материал в нашем <a href="/maldives/travel-guide/gaafu-atoll-fishing-guide-mfh-maamendhoo/">гиде по рыбалке на атолле Гаафу</a>.</p>', 'Сезоны рыбалки на Мальдивах: гид по месяцам | Путеводитель по Мальдивам | MTG', 'Когда лучше ловить каждый вид на мальдивских атоллах — от сезона тунца и вахоо во время северо-восточного муссона до последующего сезона гигантского каранкса.', 'published', 'claude'),
  ('e5d2ab2f-5701-4232-86ba-4e1748b41605', 'article', 'ru', 'gde-nahodyatsya-maldivy', 'Где находятся Мальдивы?', 'Где находятся Мальдивы? Узнайте, где расположен этот тропический рай и почему это одно из любимых направлений путешественников со всего мира.', null, '<h2>Общий обзор расположения Мальдив</h2><p>Мальдивы, официально Мальдивская Республика, — это тропический рай, расположенный в Индийском океане. Находясь к юго-западу от Шри-Ланки и Индии, Мальдивы представляют собой цепь из 26 атоллов, состоящих из более чем 1000 коралловых островов. Эта прекрасная страна славится своими потрясающими белоснежными пляжами, кристально чистой бирюзовой водой и яркими коралловыми рифами, что делает её желанным направлением для путешественников, ищущих спокойствие и природную красоту.</p><h2>Карта Мальдив</h2><h2>Географические координаты</h2><figure><img src="legacy/images/maps/maldives-location-map.webp" alt="Карта расположения Мальдив" loading="lazy" /></figure><p>Мальдивы расположены стратегически примерно в 7 градусах к северу от экватора, что обеспечивает тёплый тропический климат круглый год. Географические координаты Мальдив составляют примерно 3°15'' северной широты и 73°00'' восточной долготы. Это расположение помещает Мальдивы в центр Индийского океана, вдали от любой крупной суши, что способствует их уединённой и спокойной атмосфере.</p><h2>Близость к соседним странам</h2><figure><img src="legacy/images/maps/location-of-maldives.webp" alt="Расположение Мальдив" loading="lazy" /></figure><p>Мальдивы находятся примерно в 700 километрах к юго-западу от Шри-Ланки и в 400 километрах к юго-западу от Индии. Эта близость к Южной Азии делает Мальдивы легкодоступными по воздуху из крупных городов региона, таких как Коломбо, Мумбаи и Бангалор. Столица <a href="/maldives/islands/male/">Мале</a>, расположенная на одном из островов, служит главными воротами на Мальдивы, с международным аэропортом, соединяющим страну с остальным миром.</p><h2>Атоллы Мальдив</h2><figure><img src="legacy/images/maps/maldives-atoll-map.webp" alt="Карта атоллов Мальдив" loading="lazy" /></figure><p>Мальдивы состоят из 26 природных атоллов, разбросанных на площади примерно 90 000 квадратных километров. Эти атоллы разделены на 20 административных регионов, каждый из которых состоит из множества небольших островов. Уникальность Мальдив в том, что их суша относительно невелика, но они занимают обширную океанскую территорию. Крупнейший атолл Мальдив — атолл Баа, который также является биосферным заповедником ЮНЕСКО, известным своим богатым биоразнообразием и нетронутой морской средой.</p><h2>Значение расположения Мальдив</h2><figure><img src="legacy/images/maps/indian-ocean.webp" alt="Значение расположения Мальдив" loading="lazy" /></figure><p>Расположение Мальдив важно по нескольким причинам. Во-первых, близость к экватору обеспечивает тёплый и солнечный климат круглый год, что делает их идеальным направлением для любителей пляжного отдыха и водных видов спорта. Во-вторых, уединённость Мальдив посреди Индийского океана создаёт ощущение удалённости и эксклюзивности, высоко ценимое туристами, ищущими спокойный отдых. Наконец, окружающие океанские воды хранят одни из самых красивых коралловых рифов и морской жизни в мире, что делает Мальдивы первоклассным направлением для снорклинга и дайвинга.</p><h2>Как добраться до Мальдив</h2><p>Добраться до Мальдив относительно просто благодаря прямым рейсам из нескольких крупных городов мира. Большинство посетителей прибывают в Velana International Airport, расположенный на острове Хулхуле рядом со столицей Мале. Оттуда путешественники добираются до своих курортных островов на скоростном катере, гидросамолёте или внутреннем рейсе, в зависимости от расстояния от аэропорта. Удалённое расположение Мальдив означает, что по прибытии вас окружит спокойствие океана, и единственным звуком будет шум волн.</p><h2>Заключение: удалённый тропический рай</h2><p>Расположение Мальдив посреди Индийского океана делает их по-настоящему уникальным направлением. Их географическое положение в сочетании с природной красотой и спокойной атмосферой привлекает гостей со всего мира. Планируете ли вы романтическое путешествие, семейный отдых или отпуск, полный приключений, — Мальдивы предложат что-то для каждого на фоне одного из самых красивых мест на Земле.</p>', 'Где находятся Мальдивы? | Путеводитель по Мальдивам | MTG', 'Где находятся Мальдивы? Узнайте, где расположен этот тропический рай и почему это одно из любимых направлений путешественников со всего мира.', 'published', 'claude')
